public record Port(string Id,string Label,string Family,JsonNode Node){
 public DateTimeOffset SortUtc{
  get{
   foreach(var key in new[]{"addedUtc","savedUtc","downloadedUtc","builtUtc"})
    if(DateTimeOffset.TryParse(Node[key]?.ToString(),System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.AssumeUniversal,out var date))return date;
   return DateTimeOffset.MinValue;
  }
 }
 public string DateLabel{
  get{
   foreach(var (key,label) in new[]{("builtUtc","Собрано"),("savedUtc","Сохранено"),("downloadedUtc","Скачано"),("addedUtc","Добавлено"),("installedUtc","Установлено")}){
    var date=FormatDate(Node[key]?.ToString());if(date.Length>0)return label+" "+date;
   }
   return "дата не сохранена";
  }
 }
